{
  "command": "cd /tmp/eval-clean; head -5 fixtures/ledger.csv; echo \"--- metrics\"; cat fixtures/metrics.csv; echo \"--- p5 dir\"; ls -la runs/p5; echo \"--- notes\"; ls -la fixtures/notes",
  "timeout": 10
}

{
  "command": "cd /tmp/eval-clean; python3 - <<'EOF'
import csv, collections
rows=list(csv.DictReader(open('fixtures/ledger.csv')))
print("raw regions:", sorted({repr(r['region']) for r in rows}))
ids=[r['id'] for r in rows]
print("unique ids", len(set(ids)), "of", len(ids))
print("dup ids", [k for k,v in collections.Counter(ids).items() if v>1][:5])
nonnum=[]
for r in rows:
    try: float(r['revenue'])
    except Exception: nonnum.append(r)
print("nonnumeric revenue", len(nonnum), nonnum[:3])
print("refunded values", collections.Counter(r['refunded'] for r in rows))
EOF
echo "--- files under fixtures recursively"; find fixtures -type f | sort",
  "timeout": 15
}

